import React, { useState, useRef, useEffect } from "react";
import { MessageCircle, X, Send, Bot, User } from "lucide-react";
import "../App.css"; 

export default function Chatbot() {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState([
    { text: "Hi! I'm Vidya AI. Ask me anything about your lessons!", sender: "bot" }
  ]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  
  // Auto-scroll to bottom
  const messagesEndRef = useRef(null);
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };
  useEffect(scrollToBottom, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    // 1. Add User Message immediately
    const userMessage = { text: input, sender: "user" };
    setMessages((prev) => [...prev, userMessage]);
    setInput("");
    setIsLoading(true);

    try {
      // 2. Connect to your existing Backend
      // NOTE: Using the standard port 4000 as discussed before.
      const response = await fetch("http://localhost:4000/api/chatbot", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: userMessage.text }),
      });

      const data = await response.json();
      
      // 3. Add Bot Response
      const botMessage = { text: data.reply, sender: "bot" };
      setMessages((prev) => [...prev, botMessage]);
    } catch (error) {
      console.error("Error:", error);
      setMessages((prev) => [...prev, { text: "I'm having trouble connecting to the server. Please try again later.", sender: "bot" }]);
    }
    setIsLoading(false);
  };

  return (
    <>
      {/* 1. Floating Button (Visible when chat is closed) */}
      {!isOpen && (
        <div className="chatbot-float-btn" onClick={() => setIsOpen(true)}>
          <MessageCircle size={32} />
        </div>
      )}

      {/* 2. Chat Window (Visible when open) */}
      {isOpen && (
        <div className="chatbot-window">
          
          {/* Header */}
          <div className="chatbot-header">
            <div style={{display:'flex', alignItems:'center', gap:'10px'}}>
                <div style={{background:'rgba(255,255,255,0.2)', padding:'6px', borderRadius:'50%'}}>
                   <Bot size={20} color="white" />
                </div>
                <span style={{fontWeight:'700', fontSize:'1.1rem'}}>Vidya AI Tutor</span>
            </div>
            <X size={24} style={{cursor:'pointer', opacity:0.8}} onClick={() => setIsOpen(false)} />
          </div>

          {/* Messages List */}
          <div className="chatbot-messages">
            {messages.map((msg, index) => (
              <div key={index} className={`message-row ${msg.sender === "user" ? "user-row" : "bot-row"}`}>
                
                {msg.sender === "bot" && (
                   <div className="chat-avatar bot-avatar"><Bot size={16} /></div>
                )}

                <div className={`message-bubble ${msg.sender === "user" ? "user-bubble" : "bot-bubble"}`}>
                  {msg.text}
                </div>
              </div>
            ))}
            
            {isLoading && (
              <div className="message-row bot-row">
                 <div className="chat-avatar bot-avatar"><Bot size={16} /></div>
                 <div className="message-bubble bot-bubble" style={{fontStyle:'italic', opacity:0.7}}>
                    Thinking...
                 </div>
              </div>
            )}
            
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div className="chatbot-input-area">
            <input
              type="text"
              placeholder="Type your question..."
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyPress={(e) => e.key === "Enter" && handleSend()}
            />
            <button className="btn-send" onClick={handleSend} disabled={isLoading}>
              <Send size={18} />
            </button>
          </div>

        </div>
      )}
    </>
  );
}
